import http from "node:http";
import https from "node:https";

function isDenied(error) {
  for (let current = error; current; current = current.cause) {
    if (current.name === "NotCapable") return true;
    if (current.code === "EACCES" || current.code === "ERR_ACCESS_DENIED") {
      return true;
    }
    if (current.message?.startsWith("oden capsec:")) return true;
  }
  return false;
}

function boundedRequest(makeRequest, socket, destroySocket = true) {
  let request;
  return Promise.race([
    new Promise((resolve, reject) => {
      try {
        request = makeRequest();
        request.once("error", reject);
        request.once("response", (response) => {
          response.resume();
          response.once("end", () => resolve("connected"));
          response.once("error", reject);
        });
        request.end();
      } catch (error) {
        reject(error);
      }
    }),
    new Promise((_, reject) =>
      setTimeout(
        () => reject(new Error("borrowed socket request timed out")),
        2_000,
      )
    ),
  ]).catch((error) => {
    if (isDenied(error)) return "denied";
    throw error;
  }).finally(() => {
    request?.destroy();
    if (destroySocket) socket.destroy();
  });
}

function options(url) {
  const parsed = new URL(url);
  return {
    protocol: parsed.protocol,
    hostname: parsed.hostname,
    port: parsed.port,
    path: `${parsed.pathname}${parsed.search}`,
  };
}

export function requestWithCreateConnectionSocket(socket, url) {
  return boundedRequest(
    () =>
      http.request({
        ...options(url),
        agent: null,
        createConnection: () => {
          throw new Error("closed createConnection hook was invoked");
        },
      }),
    socket,
  );
}

export function requestWithExternalCreateConnectionSocket(
  socket,
  url,
  createConnection,
) {
  return boundedRequest(
    () =>
      http.request({
        ...options(url),
        agent: null,
        createConnection,
      }),
    socket,
  );
}

export function requestWithAgentLikeSocket(socket, url) {
  return boundedRequest(
    () =>
      http.request({
        ...options(url),
        agent: {
          protocol: "http:",
          addRequest() {
            throw new Error("closed Agent-like addRequest was invoked");
          },
        },
      }),
    socket,
  );
}

export function requestWithDelayedAgentLikeSocket(socket, url, agent) {
  return boundedRequest(
    () =>
      http.request({
        ...options(url),
        agent,
      }),
    socket,
  );
}

export function requestWithAgent(url, agent) {
  return boundedRequest(
    () => http.request({ ...options(url), agent }),
    { destroy() {} },
    false,
  );
}

export function requestWithFalsyAgent(url) {
  return boundedRequest(
    () => http.request({ ...options(url), agent: 0 }),
    { destroy() {} },
    false,
  );
}

export function requestHttps(url, agent = undefined) {
  return boundedRequest(
    () =>
      https.request({
        ...options(url),
        agent,
        rejectUnauthorized: false,
      }),
    { destroy() {} },
    false,
  );
}

function unixOptions(socketPath) {
  return { path: "/ok", socketPath };
}

export function requestWithUnixCreateConnectionSocket(socket, socketPath) {
  return boundedRequest(
    () =>
      http.request({
        ...unixOptions(socketPath),
        agent: null,
        createConnection: () => {
          throw new Error("closed Unix createConnection hook was invoked");
        },
      }),
    socket,
  );
}

export function requestWithUnixAgentLikeSocket(socket, socketPath) {
  return boundedRequest(
    () =>
      http.request({
        ...unixOptions(socketPath),
        agent: {
          protocol: "http:",
          addRequest() {
            throw new Error("closed Unix Agent-like addRequest was invoked");
          },
        },
      }),
    socket,
  );
}

export async function requestWithReusedAgentLikeSocket(socket, url) {
  const makeRequest = () =>
    http.request({
      ...options(url),
      agent: null,
      createConnection: () => {
        throw new Error("closed reused createConnection hook was invoked");
      },
    });
  const first = await boundedRequest(makeRequest, socket, false);
  if (first !== "connected") {
    socket.destroy();
    return first;
  }
  return await boundedRequest(makeRequest, socket);
}

function nativeCheck(check) {
  try {
    return check() === 0 ? "connected" : "denied";
  } catch (error) {
    if (isDenied(error)) return "denied";
    throw error;
  }
}

export function checkNativeTcpSocket(socket, url) {
  const parsed = new URL(url);
  return nativeCheck(() =>
    socket._handle.checkOdenHttpSocketUse(
      parsed.hostname,
      Number(parsed.port),
      "node:http.request()",
      true,
    ));
}

export function checkNativeUnixSocket(socket, socketPath) {
  return nativeCheck(() =>
    socket._handle.checkOdenHttpSocketUse(
      socketPath,
      "node:http.request()",
    ));
}

export function requestWithHttpsSocket(socket, url) {
  return boundedRequest(
    () =>
      https.request({
        ...options(url),
        rejectUnauthorized: false,
        socket,
      }),
    socket,
  );
}

export async function requestWithAlternatingPort(url, alternatePort) {
  const parsed = new URL(url);
  let reads = 0;
  const outcome = await boundedRequest(
    () =>
      http.request({
        protocol: parsed.protocol,
        hostname: parsed.hostname,
        get port() {
          reads++;
          return reads === 1 ? parsed.port : alternatePort;
        },
        path: `${parsed.pathname}${parsed.search}`,
      }),
    { destroy() {} },
    false,
  );
  return { outcome, reads };
}

export async function requestWithAlternatingPortCoercion(url, alternatePort) {
  const parsed = new URL(url);
  let reads = 0;
  const port = {
    valueOf() {
      reads++;
      return reads === 1 ? Number(parsed.port) : Number(alternatePort);
    },
  };
  try {
    const outcome = await boundedRequest(
      () =>
        http.request({
          protocol: parsed.protocol,
          hostname: parsed.hostname,
          port,
          path: `${parsed.pathname}${parsed.search}`,
        }),
      { destroy() {} },
      false,
    );
    return { outcome, reads };
  } catch (error) {
    if (error?.code === "ERR_SOCKET_BAD_PORT") {
      return { outcome: "denied", reads };
    }
    throw error;
  }
}

export async function requestWithInvalidPortString(url, port) {
  const parsed = new URL(url);
  try {
    const outcome = await boundedRequest(
      () =>
        http.request({
          protocol: parsed.protocol,
          hostname: parsed.hostname,
          port,
          path: `${parsed.pathname}${parsed.search}`,
        }),
      { destroy() {} },
      false,
    );
    return outcome;
  } catch (error) {
    if (error?.code === "ERR_SOCKET_BAD_PORT") return "denied";
    throw error;
  }
}

export async function requestWithAlternatingHostname(url, alternateHostname) {
  const parsed = new URL(url);
  let reads = 0;
  const outcome = await boundedRequest(
    () =>
      http.request({
        protocol: parsed.protocol,
        get hostname() {
          reads++;
          return reads === 1 ? parsed.hostname : alternateHostname;
        },
        port: parsed.port,
        path: `${parsed.pathname}${parsed.search}`,
      }),
    { destroy() {} },
    false,
  );
  return { outcome, reads };
}

export async function requestWithAlternatingSocketPath(
  socketPath,
  alternatePath,
) {
  let reads = 0;
  const outcome = await boundedRequest(
    () =>
      http.request({
        get socketPath() {
          reads++;
          return reads === 1 ? socketPath : alternatePath;
        },
        path: "/ok",
      }),
    { destroy() {} },
    false,
  );
  return { outcome, reads };
}
